 16	export interface SessionSyncSchedulerOptions {
 17	  /** Path to session worktree (e.g., /project/.kspec-sessions) */
 18	  worktreeDir: string;
 19	  /** Sync interval in seconds (0 = disabled) */
 20	  intervalSeconds: number;
