 24	  pubsub?: SessionSyncPubSub;
 25	}
 26	
 27	/**
 28	 * Minimal pubsub interface for broadcasting sync events.
 29	 */
 30	export interface SessionSyncPubSub {
 31	  broadcast(
 32	    channel: string,
 33	    type: string,
 34	    data: Record<string, unknown>,
 35	  ): void;
 36	}
 37	
 38	/**
 39	 * Manages periodic background session branch pull for the daemon.
 40	 *
 41	 * AC: @session-branch-worktree ac-sync
 42	 */
 43	export class SessionSyncScheduler {
 44	  private timer: ReturnType<typeof setInterval> | null = null;
 45	  private running = false;
 46	  private readonly worktreeDir: string;
 47	  private readonly intervalMs: number;
 48	  private readonly branchName: string;
 49	  private readonly pubsub?: SessionSyncPubSub;
 50	
 51	  constructor(options: SessionSyncSchedulerOptions) {
 52	    this.worktreeDir = options.worktreeDir;
 53	    this.intervalMs = options.intervalSeconds * 1000;
 54	    this.branchName = options.branchName;
 55	    this.pubsub = options.pubsub;
 56	  }
 57	
 58	  /**
 59	   * Start the periodic sync scheduler.
 60	   * Does nothing if interval is 0 or already started.
 61	   */
 62	  start(): void {
 63	    if (this.intervalMs <= 0 || this.timer !== null) {
 64	      return;
 65	    }
 66	
 67	    console.log(
 68	      `[daemon] Session sync scheduler started (interval: ${this.intervalMs / 1000}s)`,
 69	    );
 70	
 71	    this.timer = setInterval(() => {
 72	      this.syncOnce().catch((err) => {
 73	        console.error("[daemon] Session sync error:", err);
 74	      });
 75	    }, this.intervalMs);
 76	
 77	    // Don't prevent process exit
 78	    if (
 79	      this.timer &&
 80	      typeof this.timer === "object" &&
 81	      "unref" in this.timer
 82	    ) {
 83	      this.timer.unref();
 84	    }
 85	  }
 86	
 87	  /**
 88	   * Stop the periodic sync scheduler.
 89	   */
 90	  stop(): void {
 91	    if (this.timer !== null) {
 92	      clearInterval(this.timer);
 93	      this.timer = null;
 94	      console.log("[daemon] Session sync scheduler stopped");
 95	    }
 96	  }
 97	
 98	  /**
 99	   * Perform a single sync (pull from remote).
100	   * Skips if another sync is already in progress or no tracking configured.
101	   */
102	  async syncOnce(): Promise<void> {
103	    if (this.running) {
104	      return;
105	    }
106	
107	    const options: ShadowOptions = { branchName: this.branchName };
108	    const hasTracking = await hasRemoteTracking(this.worktreeDir, options);
109	    if (!hasTracking) {
110	      return;
111	    }
112	
113	    this.running = true;
114	    try {
115	      const result = await sessionBranchPull(
116	        this.worktreeDir,
117	        this.branchName,
118	      );
119	
120	      if (result.pulled) {
121	        console.log("[daemon] Session sync: pulled remote changes");
122	
123	        if (this.pubsub) {
124	          this.pubsub.broadcast("sessions", "session_sync", {
125	            pulled: true,
126	            hadConflict: false,
127	          });
128	        }
129	      }
130	
131	      if (result.hadConflict) {
132	        console.warn(
133	          "[daemon] Session sync: conflict detected. Run `kspec shadow resolve` to fix.",
134	        );
135	
136	        if (this.pubsub) {
137	          this.pubsub.broadcast("sessions", "session_sync", {
138	            pulled: false,
139	            hadConflict: true,
140	          });
141	        }
142	      }
143	    } finally {
144	      this.running = false;
145	    }
146	  }
147	}

