+ * No-op if sessionsDir is not a git worktree.
+ */
+async function commitAtLifecycleBoundary(
+  sessionsDir: string,
+  message: string,
+): Promise<void> {
+  if (await isSessionWorktree(sessionsDir)) {
+    await sessionBranchAutoCommit(sessionsDir, message);
+  }
+}
